// ParseStructTags checks the full Go tag syntax and rejects repeated owned keys.
// Values are private metadata and must never be copied into public artifacts.
func ParseStructTags(tag string) (map[string]string, error) {
	values := make(map[string]string)
	entries := 0
	for tag != "" {
		if entries > 0 && tag[0] != ' ' {
			return nil, fmt.Errorf("invalid Go struct tag syntax: entries must be separated by spaces")
		}
		index := 0
		for index < len(tag) && tag[index] == ' ' {
			index++
		}
		tag = tag[index:]
		if tag == "" {
			break
		}

		index = 0
		for index < len(tag) && tag[index] > ' ' && tag[index] != ':' && tag[index] != '"' && tag[index] != 0x7f {
			index++
		}
		if index == 0 || index+1 >= len(tag) || tag[index] != ':' || tag[index+1] != '"' {
			return nil, fmt.Errorf("invalid Go struct tag syntax")
		}
		key := tag[:index]
		tag = tag[index+1:]

		index = 1
		for index < len(tag) && tag[index] != '"' {
			if tag[index] == '\\' {
				index++
			}
			index++
		}
		if index >= len(tag) {
			return nil, fmt.Errorf("invalid Go struct tag syntax")
		}
		quotedValue := tag[:index+1]
		tag = tag[index+1:]
		value, err := strconv.Unquote(quotedValue)
		if err != nil {
			return nil, fmt.Errorf("invalid Go struct tag syntax")
		}
		if _, duplicate := values[key]; duplicate {
			switch key {
			case "yaml", "plystra", "plystra-default":
				return nil, fmt.Errorf("duplicate Go struct tag key %q", key)
			}
		} else {
			values[key] = value
		}
		entries++
	}
	return values, nil
}

// FieldPolicy validates the closed Plystra policy options used by discovery and startup.
func FieldPolicy(tags map[string]string) (bool, bool, error) {
	value, exists := tags["plystra"]
	if !exists {
		return false, false, nil
	}
	if value == "" {
		return false, false, fmt.Errorf("plystra configuration tag must name at least one option")
	}
	required := false
	buildVisible := false
	for _, option := range strings.Split(value, ",") {
		switch option {
		case "required":
			if required {
				return false, false, fmt.Errorf("duplicate plystra configuration option %q", option)
			}
			required = true
		case "build-visible":
			if buildVisible {
				return false, false, fmt.Errorf("duplicate plystra configuration option %q", option)
			}
			buildVisible = true
		default:
			return false, false, fmt.Errorf("unknown plystra configuration option %q", option)
		}
	}
	return required, buildVisible, nil
}

// BindDefaults reads defaults from the already compiled Config type. Generated
// source contains no copied default literal or digest of private defaults.
func BindDefaults(s *Schema, t reflect.Type) error {
	if s == nil || t == nil {
		return ErrValue
	}
	if !matchesType(*s, t) {
		return ErrValue
	}
	if s.Element != nil {
		if t.Kind() != reflect.Pointer && t.Kind() != reflect.Array && t.Kind() != reflect.Slice && t.Kind() != reflect.Map {
			return ErrValue
		}
		return BindDefaults(s.Element, t.Elem())
	}
	fieldTags := make(map[string]map[string]string, len(s.Fields))
	if s.Kind == "object" {
		for i := 0; i < t.NumField(); i++ {
			field := t.Field(i)
			tags, err := ParseStructTags(string(field.Tag))
			if err != nil {
				return ErrValue
			}
			yamlName, tagged := tags["yaml"]
			_, policy := tags["plystra"]
			_, defaulted := tags["plystra-default"]
			if !field.IsExported() {
				if tagged && yamlName != "-" || policy || defaulted {
					return ErrValue
				}
				continue
			}
			if field.Anonymous {
				return ErrValue
			}
			if yamlName == "-" {
				if policy || defaulted {
					return ErrValue
				}
				continue
			}
			fieldTags[field.Name] = tags
		}
	}
	for i := range s.Fields {
		f := &s.Fields[i]
		goField, ok := t.FieldByName(f.GoName)
		if !ok || goField.PkgPath != "" {
			return ErrValue
		}
		tags, exists := fieldTags[f.GoName]
		if !exists {
			return ErrValue
		}
		name := tags["yaml"]
		if name == "" {
			name = strings.ToLower(goField.Name)
		}
		required, public, err := FieldPolicy(tags)
		if err != nil {
			return ErrValue
		}
		_, hasDefault := tags["plystra-default"]
		if goField.Anonymous || name != f.Name || required != f.Required || public != f.BuildVisible || hasDefault != f.HasDefault {
			return ErrValue
		}
		if required && hasDefault {
			return ErrValue
		}
		if f.HasDefault {
			value, exists := tags["plystra-default"]
			if !exists {
				return ErrValue
			}
			switch f.Value.Kind {
			case "string":
				f.Default, _ = json.Marshal(value)
			case "duration":
				parsed, err := time.ParseDuration(value)
				if err != nil {
					return ErrValue
				}
				f.Default, _ = json.Marshal(parsed.String())
			case "url":
				parsed, err := url.Parse(value)
				if err != nil {
					return ErrValue
				}
				f.Default, _ = json.Marshal(parsed.String())
			case "signed-integer":
				v, err := strconv.ParseInt(value, 10, f.Value.Bits)
				if err != nil {
					return ErrValue
				}
				f.Default = []byte(strconv.FormatInt(v, 10))
			case "unsigned-integer":
				v, err := strconv.ParseUint(value, 10, f.Value.Bits)
				if err != nil {
					return ErrValue
				}
				f.Default = []byte(strconv.FormatUint(v, 10))
			case "number":
				v, err := strconv.ParseFloat(value, f.Value.Bits)
				if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
					return ErrValue
				}
				f.Default = []byte(strconv.FormatFloat(v, 'g', -1, f.Value.Bits))
			default:
				f.Default = []byte(value)
			}
			// An authored override must not hide an invalid compiled default.
			node, err := defaultNode(f.Value, f.Default)
			if err != nil {
				return ErrValue
			}
			if _, err := Normalize(f.Value, node); err != nil {
				return ErrValue
			}
		}
		if err := BindDefaults(&f.Value, goField.Type); err != nil {
			return err
		}
	}
	return nil
}

// DefaultsJSON is private deployment evidence, never a generated-source identity.
func DefaultsJSON(s Schema) ([]byte, error) {
	defaults := make(map[string]json.RawMessage)
	var visit func(Schema, string)
	visit = func(s Schema, path string) {
		if s.Element != nil {
			visit(*s.Element, path+"/*")
		}
		for _, f := range s.Fields {
			key := path + "/" + strings.ReplaceAll(strings.ReplaceAll(f.Name, "~", "~0"), "/", "~1")
			if f.HasDefault {
				defaults[key] = f.Default
			}
			visit(f.Value, key)
		}
	}
	visit(s, "")
	return json.Marshal(defaults)
}

// RestoreDefaults binds one canonical private default inventory to a detached
// discovery-derived schema. It performs no Go loading or Secret resolution.
func RestoreDefaults(s *Schema, data []byte) error {
	var defaults map[string]json.RawMessage
	if s == nil || json.Unmarshal(data, &defaults) != nil || defaults == nil {
		return invalid("config", "invalid private defaults")
	}
	canonical, err := json.Marshal(defaults)
	if err != nil || !bytes.Equal(canonical, data) {
		return invalid("config", "invalid private defaults")
	}
	count := 0
	var visit func(*Schema, string, int) error
	visit = func(schema *Schema, path string, depth int) error {
		count++
		if depth > 64 || count > 65536 {
			return invalid("config", "configuration exceeds traversal bounds")
		}
		if schema.Element != nil {
			if err := visit(schema.Element, path+"/*", depth+1); err != nil {
				return err
			}
		}
		for i := range schema.Fields {
			field := &schema.Fields[i]
			key := path + "/" + strings.ReplaceAll(strings.ReplaceAll(field.Name, "~", "~0"), "/", "~1")
			if field.HasDefault {
				value, exists := defaults[key]
				if !exists || bytes.Equal(value, []byte("null")) {
					return invalid("config", "invalid private defaults")
				}
				node, err := defaultNode(field.Value, value)
				if err != nil {
					return invalid("config", "invalid private defaults")
				}
				if _, err := Normalize(field.Value, node); err != nil {
					return invalid("config", "invalid private defaults")
				}
				field.Default = append(json.RawMessage(nil), value...)
				delete(defaults, key)
			}
			if err := visit(&field.Value, key, depth+1); err != nil {
				return err
			}
		}
		return nil
	}
	if err := visit(s, "", 0); err != nil {
		return err
	}
	if len(defaults) != 0 {
		return invalid("config", "invalid private defaults")
	}
	return nil
}

func matchesType(s Schema, t reflect.Type) bool {
	switch s.Kind {
	case "string":
		return t.Kind() == reflect.String
	case "boolean":
		return t.Kind() == reflect.Bool
	case "signed-integer":
		return t.Kind() >= reflect.Int && t.Kind() <= reflect.Int64 && (t.Kind() == reflect.Int && s.Bits == 32 || t.Bits() == s.Bits)
	case "unsigned-integer":
		return t.Kind() >= reflect.Uint && t.Kind() <= reflect.Uint64 && (t.Kind() == reflect.Uint && s.Bits == 32 || t.Bits() == s.Bits)
	case "number":
		return (t.Kind() == reflect.Float32 || t.Kind() == reflect.Float64) && t.Bits() == s.Bits
	case "duration":
		return t == reflect.TypeFor[time.Duration]()
	case "url":
		return t == reflect.TypeFor[url.URL]()
	case "secret":
		return t == reflect.TypeFor[configuration.Secret]()
	case "pointer":
		return t.Kind() == reflect.Pointer && s.Element != nil
	case "list":
		return s.Element != nil && (s.Length == nil && t.Kind() == reflect.Slice || s.Length != nil && t.Kind() == reflect.Array && *s.Length == int64(t.Len()))
	case "map":
		return t.Kind() == reflect.Map && t.Key().Kind() == reflect.String && s.Element != nil
	case "object":
		if t.Kind() != reflect.Struct {
			return false
		}
		count := 0
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			if f.IsExported() && f.Tag.Get("yaml") != "-" {
				count++
			}
		}
		return count == len(s.Fields)
	default:
		return false
	}
}

// Bind assigns a normalized value through exact generated Go fields. It never
// invokes user-defined unmarshalling methods. All objects must be validated and
// compatibility-checked before the first call, because this resolves Secrets.
func Bind(ctx context.Context, resolver *configuration.Resolver, s Schema, n *yaml.Node, target any) error {
	v := reflect.ValueOf(target)
	if v.Kind() != reflect.Pointer || v.IsNil() {
		return ErrValue
	}
	return bind(ctx, resolver, s, n, v.Elem())
}

func bind(ctx context.Context, resolver *configuration.Resolver, s Schema, n *yaml.Node, v reflect.Value) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if n == nil || null(n) {
		return nil
	}
	switch s.Kind {
	case "object":
		m, _ := mapping(n, "")
		for _, f := range s.Fields {
			if err := bind(ctx, resolver, f.Value, m[f.Name], v.FieldByName(f.GoName)); err != nil {
				return err
			}
		}
	case "pointer":
		v.Set(reflect.New(v.Type().Elem()))
		return bind(ctx, resolver, *s.Element, n, v.Elem())
	case "list":
		if v.Kind() == reflect.Slice {
			v.Set(reflect.MakeSlice(v.Type(), len(n.Content), len(n.Content)))
		}
		for i, child := range n.Content {
			if err := bind(ctx, resolver, *s.Element, child, v.Index(i)); err != nil {
				return err
			}
		}
	case "map":
		v.Set(reflect.MakeMapWithSize(v.Type(), len(n.Content)/2))
		for i := 0; i < len(n.Content); i += 2 {
			key, value := reflect.New(v.Type().Key()).Elem(), reflect.New(v.Type().Elem()).Elem()
			key.SetString(n.Content[i].Value)
			if err := bind(ctx, resolver, *s.Element, n.Content[i+1], value); err != nil {
				return err
			}
			v.SetMapIndex(key, value)
		}
	case "string":
		v.SetString(n.Value)
	case "boolean":
		v.SetBool(n.Value == "true")
	case "signed-integer":
		value, _ := strconv.ParseInt(n.Value, 10, s.Bits)
		v.SetInt(value)
	case "unsigned-integer":
		value, _ := strconv.ParseUint(n.Value, 10, s.Bits)
		v.SetUint(value)
	case "number":
		value, _ := strconv.ParseFloat(n.Value, s.Bits)
		v.SetFloat(value)
	case "duration":
		value, _ := time.ParseDuration(n.Value)
		v.SetInt(int64(value))
	case "url":
		value, _ := url.Parse(n.Value)
		v.Set(reflect.ValueOf(*value))
	case "secret":
		ref, err := reference(n)
		if err != nil {
			return ErrValue
		}
		secret, err := resolver.Resolve(ctx, ref)
		if err != nil {
			return fmt.Errorf("resolve constructor Secret: %w", err)
		}
		v.Set(reflect.ValueOf(secret))
	default:
		return ErrValue
	}
	return nil
}
